import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, {alpha} complex numbers z_n (1 ≤ n ≤ {alpha}) are given, each with nonzero real and imaginary parts. Let d_n denote the Euclidean distance from the point (n, |z_n|) to the line y = ({slope_num}/{slope_den})x + {intercept}, where gcd({slope_num}, {slope_den}) = 1 and {slope_num}^2 + {slope_den}^2 is not a perfect square. Assume {alpha} > {a_min} is prime and {alpha} ≡ {residue_mod} (mod {slope_den}). Fix distinct indices r = {idx1} and s = {idx2}, neither divisible by {slope_den}. Let t1 = {t1_num}/{t1_den} and t2 = {t2_num}/{t2_den}. Suppose the following system holds:\n\n[ Σ_{i=1}^{alpha} i^{d_i} − (({alpha} − 2) + ({idx1})^{t1} + ({idx2})^{t2}) ]^2\n+ [ Σ_{i=1}^{alpha} i^{2 d_i} − (({alpha} − 2) + ({idx1})^{2 t1} + ({idx2})^{2 t2}) ]^2\n+ [ Σ_{i=1}^{alpha} i^{3 d_i} − (({alpha} − 2) + ({idx1})^{3 t1} + ({idx2})^{3 t2}) ]^2\n+ [ Σ_{i=1}^{alpha} i^{4 d_i} − (({alpha} − 2) + ({idx1})^{4 t1} + ({idx2})^{4 t2}) ]^2\n+ [ ({idx1})^{d_{ {idx1} }} − ({idx1})^{t1} ]^2\n+ [ ({idx2})^{d_{ {idx2} }} − ({idx2})^{t2} ]^2 = 0.\n\nLet p be the maximum possible probability that the modulus |z_n| of a randomly chosen z_n is a positive integer. Determine p as a function of the given parameters.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Helper: primality test
def is_prime(n):
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    r = int(n**0.5)
    f = 3
    while f <= r:
        if n % f == 0:
            return False
        f += 2
    return True

# Choose slope_den (q) with moderate size to avoid triviality
q_choices = [5, 7, 8, 9, 11, 12, 13]
slope_den = rng.choice(q_choices)

# Choose slope_num (u), coprime to slope_den, and ensure u^2 + q^2 is not a square
def is_square(n):
    r = int(n**0.5)
    return r*r == n
slope_num = None
for _ in range(200):
    candidate = rng.randint(2, 30)
    # gcd
    def gcd(a,b):
        while b:
            a,b = b, a%b
        return a
    if gcd(candidate, slope_den) == 1 and not is_square(candidate*candidate + slope_den*slope_den):
        slope_num = candidate
        break
if slope_num is None:
    # fallback deterministic search
    for candidate in range(2, 50):
        def gcd(a,b):
            while b:
                a,b = b, a%b
            return a
        if gcd(candidate, slope_den) == 1 and not is_square(candidate*candidate + slope_den*slope_den):
            slope_num = candidate
            break
if slope_num is None:
    # Should not happen
    slope_num = 2

# Choose residue_mod in 1..q-1 to avoid trivial floor being a/q exactly with remainder 0
residue_mod = rng.randint(1, slope_den - 1)

# Choose alpha prime > a_min and congruent to residue_mod mod slope_den
a_min = rng.choice([100, 150, 200, 250])
# search range for alpha
low = a_min + 1
high = a_min + rng.randint(300, 700)
# collect primes with given congruence
candidates = []
for n in range(low, high+1):
    if n % slope_den == residue_mod and is_prime(n):
        candidates.append(n)
if not candidates:
    # expand range if needed
    high2 = high + 1000
    for n in range(high+1, high2+1):
        if n % slope_den == residue_mod and is_prime(n):
            candidates.append(n)
            break
if not candidates:
    # final fallback: pick next prime then adjust residue_mod accordingly
    n = low
    while not is_prime(n):
        n += 1
    alpha = n
    residue_mod = alpha % slope_den
else:
    alpha = rng.choice(candidates)

# Choose intercept (integer)
intercept = rng.randint(800, 5000)

# Choose two distinct indices not divisible by slope_den
usable = [i for i in range(1, alpha+1) if i % slope_den != 0]
if len(usable) < 2:
    # should not happen for reasonable alpha and slope_den
    return None
idx1, idx2 = rng.sample(usable, 2)

# Choose rational exponents t1 and t2 (small, positive)
den_choices = [2, 3, 4, 5, 6]
t1_den = rng.choice(den_choices)
t2_den = rng.choice([d for d in den_choices if d != t1_den])
t1_num = rng.randint(1, 9)
t2_num = rng.randint(1, 9)

return {
    'alpha': alpha,
    'slope_num': slope_num,
    'slope_den': slope_den,
    'intercept': intercept,
    'a_min': a_min,
    'residue_mod': residue_mod,
    'idx1': idx1,
    'idx2': idx2,
    't1_num': t1_num,
    't1_den': t1_den,
    't2_num': t2_num,
    't2_den': t2_den
}

    def verifier(assign):
# Validate presence of required keys
required = ['alpha','slope_num','slope_den','intercept','a_min','residue_mod','idx1','idx2','t1_num','t1_den','t2_num','t2_den']
for k in required:
    if k not in assign:
        # Missing key
        return False, None  # missing fields

alpha = assign['alpha']
slope_num = assign['slope_num']
slope_den = assign['slope_den']
intercept = assign['intercept']
a_min = assign['a_min']
residue_mod = assign['residue_mod']
idx1 = assign['idx1']
idx2 = assign['idx2']

# Basic validations
def is_prime(n):
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    r = int(n**0.5)
    f = 3
    while f <= r:
        if n % f == 0:
            return False
        f += 2
    return True

if not is_prime(alpha):
    return False, None  # alpha must be prime
if not (alpha > a_min):
    return False, None  # alpha must exceed a_min
if alpha % slope_den != residue_mod:
    return False, None  # residue mismatch

# gcd check
def gcd(a,b):
    while b:
        a,b = b, a%b
    return a
if gcd(slope_num, slope_den) != 1:
    return False, None  # must be coprime slope

# irrational sqrt condition: slope_num^2 + slope_den^2 not a perfect square
def is_square(n):
    r = int(n**0.5)
    return r*r == n
if is_square(slope_num*slope_num + slope_den*slope_den):
    return False, None  # violates irrationality guard

# idx checks
if not (1 <= idx1 <= alpha and 1 <= idx2 <= alpha and idx1 != idx2):
    return False, None  # invalid indices
if idx1 % slope_den == 0 or idx2 % slope_den == 0:
    return False, None  # exceptions must not lie at multiples of slope_den to avoid trivial reduction in integer count

# Given the constraints in the wrapper, all i != idx1, idx2 must satisfy d_i = 0 (i.e., points lie on the line),
# and at i = idx1, idx2 we have d_{idx1} = t1 and d_{idx2} = t2 (forced nonzero). Because intercept is integer and slope is slope_num/slope_den with gcd=1,
# y(n) is an integer iff slope_den divides slope_num * n, equivalently slope_den divides n.
# The two exceptions are chosen so they are NOT multiples of slope_den, hence all multiples of slope_den in {1,...,alpha} lie on the line.
# For those n with slope_den | n, |z_n| equals the line value and thus is an integer.
# For the two forced nonzero distances, |z_n| = line(n) ± d_n * sqrt(1 + (slope_num/slope_den)^2), and sqrt(...) is irrational; with d_n > 0, this sum is irrational, so these moduli cannot be integers.

floor_count = alpha // slope_den
# Maximum probability is number of integers among moduli divided by alpha.
num = floor_count
den = alpha
g = gcd(num, den)
num //= g
den //= g
answer = f"{num}/{den}"
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")
